                may.id(),
                new NewReservation(
                        may.roomNumber(),
                        may.guest(),
                        may.checkIn(),
                        may.checkOut(),
                        3, // 3 guests
                        may.ratePlan()),
                may.price());
        store.save(newMay);
        service.confirm(newMay.id());

        String csv = new TourismTaxReport(store).generate(YearMonth.of(2027, 5));

        // 3 guests, 3 nights, 4.50 each: 40.50
